ruleToc.nextTocUrl:
@js:
pages=java.getString("#pagestats@textNodes");
n=String(pages).replace(/\//, "");

try {
  var list = [];
  if (n == 1) {
    list;
  } else {
    for (var i = 2; i <= n; i++) {
      var turl = baseUrl.replace(/\d+\.html/, "");
      list.push(turl + i + ".html");
    }
  }
  list;
} catch (e) {}

n.exploreUrl:
@js:
var url=source.key,
html=java.ajax(url);
a=org.jsoup.Jsoup.parse(html)
.select("nav.nav li:lt(11) a");
var arr=[],sort=[];
if(html&&a){
	arr=Array.from(a, x=>[
		x.text(),String(x.attr("href"))
		.replace(/1/,"{{page}}")
		.replace(/quanben.+(?!1).?$/,
			"$&<,{{page}}/>")] );
		sort=arr.map(([title,link])=>({
    "title": title,
    "url": link,
    "style": {
      "layout_flexGrow": 1,
       "layout_flexBasisPercent": 0.2
    }
  }));

  JSON.stringify(sort);

	}else java.toast("发现列表获取失败！");

